CREATE TABLE IF NOT EXISTS turnos_fijos (id TEXT PRIMARY KEY, negocioId TEXT NOT NULL, espacioId TEXT NOT NULL, clientName TEXT NOT NULL, clientPhone TEXT DEFAULT '', dayOfWeek INTEGER NOT NULL CHECK(dayOfWeek BETWEEN 0 AND 6), startDate TEXT NOT NULL, endDate TEXT NOT NULL, startTime TEXT NOT NULL, endTime TEXT NOT NULL, amount REAL NOT NULL DEFAULT 0, notes TEXT DEFAULT '', activo INTEGER NOT NULL DEFAULT 1, createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL, FOREIGN KEY(negocioId) REFERENCES negocios(id) ON DELETE CASCADE, FOREIGN KEY(espacioId) REFERENCES espacios(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_turnos_fijos_negocio ON turnos_fijos(negocioId, activo);
CREATE INDEX IF NOT EXISTS idx_turnos_fijos_espacio_dias ON turnos_fijos(negocioId, espacioId, dayOfWeek, startDate, endDate, activo);
